import React, { useState } from 'react';
import { Camera, Mail, Lock } from 'lucide-react';

const LoginPage = ({ onLogin, onNavigate }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (!email || !password) {
      setError('يرجى ملء جميع الحقول');
      return;
    }

    setLoading(true);
    const result = await onLogin(email, password);
    setLoading(false);

    if (!result.success) {
      setError(result.error || 'البريد الإلكتروني أو كلمة المرور غير صحيحة');
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#0a1628] via-[#1a2942] to-[#0a1628] flex items-center justify-center p-4" dir="rtl">
      <div className="bg-[#1a2942] rounded-2xl shadow-2xl p-8 w-full max-w-md animate-fadeIn border border-[#00d4ff]/30">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-[#00d4ff] rounded-lg flex items-center justify-center mx-auto mb-4">
            <Camera className="w-10 h-10 text-[#0a1628]" />
          </div>
          <h2 className="text-3xl font-bold text-white">مرحباً بعودتك</h2>
          <p className="text-gray-300 mt-2">تسجيل الدخول إلى نظام مَكّمن</p>
        </div>

        {error && (
          <div className="bg-red-500/20 border border-red-500 text-red-400 p-3 rounded-lg mb-4 text-sm">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">البريد الإلكتروني</label>
            <div className="relative">
              <Mail className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="email"
                required
                className="w-full pr-10 pl-4 py-3 bg-[#0f1f3d] border border-[#00d4ff]/30 text-white rounded-lg focus:ring-2 focus:ring-[#00d4ff] focus:border-transparent transition"
                placeholder="ahmed@example.com"
                value={email}
                onChange={(e) => {
                  setEmail(e.target.value);
                  setError('');
                }}
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">كلمة المرور</label>
            <div className="relative">
              <Lock className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="password"
                required
                className="w-full pr-10 pl-4 py-3 bg-[#0f1f3d] border border-[#00d4ff]/30 text-white rounded-lg focus:ring-2 focus:ring-[#00d4ff] focus:border-transparent transition"
                placeholder="••••••••"
                value={password}
                onChange={(e) => {
                  setPassword(e.target.value);
                  setError('');
                }}
              />
            </div>
          </div>

          <div className="flex items-center justify-between">
            <label className="flex items-center">
              <input type="checkbox" className="w-4 h-4 text-[#00d4ff] bg-[#0f1f3d] border-[#00d4ff]/30 rounded focus:ring-[#00d4ff]" />
              <span className="mr-2 text-sm text-gray-300">تذكرني</span>
            </label>
            <button type="button" className="text-sm text-[#00d4ff] hover:text-white font-medium">
              نسيت كلمة المرور؟
            </button>
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-[#00d4ff] text-[#0a1628] py-3 rounded-lg hover:bg-[#00b8e6] font-bold shadow-md hover:shadow-lg transition-all disabled:bg-gray-600 disabled:cursor-not-allowed"
          >
            {loading ? 'جاري تسجيل الدخول...' : 'تسجيل الدخول'}
          </button>
        </form>

        <div className="mt-6 p-4 bg-[#00d4ff]/10 rounded-lg border border-[#00d4ff]/30">
          <p className="text-sm text-[#00d4ff] font-semibold mb-2">حساب تجريبي:</p>
          <p className="text-xs text-gray-300">البريد: admin@example.com</p>
          <p className="text-xs text-gray-300">كلمة المرور: admin123</p>
        </div>

        <div className="relative my-6">
          <div className="absolute inset-0 flex items-center">
            <div className="w-full border-t border-[#00d4ff]/30"></div>
          </div>
          <div className="relative flex justify-center text-sm">
            <span className="px-2 bg-[#1a2942] text-gray-400">ليس لديك حساب؟</span>
          </div>
        </div>

        <button 
          onClick={() => onNavigate('signin')} 
          className="w-full text-[#00d4ff] hover:text-white font-medium py-2 transition-colors"
        >
          إنشاء حساب جديد
        </button>

        <button 
          onClick={() => onNavigate('home')} 
          className="w-full text-gray-400 hover:text-gray-300 font-medium py-2 mt-2 transition-colors text-sm"
        >
          → العودة للرئيسية
        </button>
      </div>
    </div>
  );
};

export default LoginPage;
